def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        safe_bid = min(budget, DAILY_SALARY * 0.35)
        if hp <= 2 or no_water >= 1:
            safe_bid = min(budget, DAILY_SALARY * 0.75)
        return float(max(0.0, safe_bid))

    prev_bids = []
    urgent_count = 0
    rich_count = 0
    high_prev = 0.0
    moderate_prev = 0.0

    for opp in alive:
        if opp.get('budget', 0) >= 700:
            rich_count += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_count += 1
        prev = opp.get('previous_trace', {})
        bid = None
        if isinstance(prev, dict):
            bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if float(bid) > high_prev:
                high_prev = float(bid)
            if float(bid) >= DAILY_SALARY * 0.9:
                moderate_prev += 1

    slots = int(supply / WATER_REQ)
    if slots < 1:
        slots = 1

    pressure = len(alive) - slots

    if prev_bids:
        sorted_bids = sorted(prev_bids)
        median_prev = sorted_bids[int(len(sorted_bids) // 2)]
        low_prev = sorted_bids[0]
    else:
        median_prev = DAILY_SALARY * 0.7
        low_prev = DAILY_SALARY * 0.55
        high_prev = DAILY_SALARY * 0.9

    if hp <= 2 or no_water >= 2:
        target = max(DAILY_SALARY * 1.05, high_prev + 2.0)
    elif hp <= 4 or no_water >= 1:
        if pressure >= 3:
            target = max(DAILY_SALARY * 0.95, high_prev + 1.0)
        else:
            target = max(DAILY_SALARY * 0.82, median_prev + 1.0)
    else:
        if slots >= len(alive):
            target = DAILY_SALARY * 0.28
        elif pressure <= 1:
            target = max(DAILY_SALARY * 0.42, low_prev - 2.0)
        elif pressure == 2:
            target = max(DAILY_SALARY * 0.55, median_prev - 4.0)
        else:
            if high_prev >= 100 or rich_count >= 2:
                target = DAILY_SALARY * 0.38
            else:
                target = DAILY_SALARY * 0.52

    if day >= 8 and hp >= 6 and no_water == 0:
        target *= 0.9

    if urgent_count >= 2 and hp >= 5 and no_water == 0:
        target *= 0.88

    if supply <= 16:
        target += 6.0
    elif supply >= 24:
        target -= 5.0

    cap = budget
    if hp >= 5 and no_water == 0:
        cap = min(cap, DAILY_SALARY * 1.15)
    else:
        cap = min(cap, DAILY_SALARY * 1.6)

    bid = min(cap, max(0.0, target))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    avg_opp_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 60.0

    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 1.2)

    if supply < 18:
        return min(my_status['budget'], max(avg_opp_bid * 1.05, DAILY_SALARY * 0.8))

    return min(my_status['budget'], max(avg_opp_bid * 0.9, DAILY_SALARY * 0.5))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        # No competition, bid low to save money
        return min(my_status['budget'], DAILY_SALARY * 0.3)

    # Collect yesterday's bids from opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Determine base bid
    if yesterday_bids:
        max_prev = max(yesterday_bids)
        base = max(DAILY_SALARY * 0.5, max_prev + 1.0)
    else:
        base = DAILY_SALARY * 0.5

    # Adjust based on health and no_water_days
    hp = my_status['hp']
    no_water = my_status['no_water_days']

    if hp <= 2 or no_water >= 2:
        # Desperate: bid high to ensure water
        bid = min(my_status['budget'], max(base, DAILY_SALARY * 0.85))
    elif hp <= 4:
        bid = min(my_status['budget'], base * 1.1)
    else:
        bid = min(my_status['budget'], base)

    # Ensure we don't bid more than budget
    bid = max(0, min(bid, my_status['budget']))
    # Round to 2 decimals to match game expectations
    return round(bid, 2)
